structs.queue_node_t:
typedef struct queue_node_t
{
    void *value;
    struct queue_node_t *next;
} queue_node_t;

structs.queue_t:
typedef struct
{
    u_int32_t size;
    queue_node_t *head;
    queue_node_t *tail;
} queue_t;

functions.queue_push:
void queue_push(queue_t *queue, void *value)
{
    queue_node_t *new_node = malloc(sizeof(queue_node_t));
    new_node->value = value;
    new_node->next = ((void *)0);
    if (queue_empty(queue))
    {
        queue->tail = new_node;
        queue->head = new_node;
    }
    else
    {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    queue->size++;
}

functions.queue_pop:
void *queue_pop(queue_t *queue)
{
    if (!queue || queue_empty(queue))
    {
        return ((void *)0);
    }
    queue_node_t *elem = queue->head;
    queue->head = queue->head->next;
    void *value = elem->value;
    if (queue->size == 1)
    {
        queue->tail = ((void *)0);
    }
    queue->size--;
    free(elem);
    return value;
}

functions.queue_front:
void *queue_front(queue_t *queue)
{
    if (!queue)
    {
        return ((void *)0);
    }
    if (queue_empty(queue))
    {
        return ((void *)0);
    }
    return queue->head->value;
}

functions.queue_back:
void *queue_back(queue_t *queue)
{
    if (!queue)
    {
        return ((void *)0);
    }
    if (queue_empty(queue))
    {
        return ((void *)0);
    }
    return queue->tail->value;
}

functions.queue_free:
void queue_free(queue_t *queue)
{
    queue_node_t *temp = queue->head;
    queue_node_t *temp2;
    while (temp)
    {
        temp2 = temp;
        temp = temp->next;
        free(temp2);
    }
}
